/*
 * Diagram viewer: no Mermaid CDN or runtime dependency.
 * SVGs are generated by Mermaid CLI at build time and committed to the repo.
 * Source remains available, selectable and copyable even with scripts disabled.
 */
(() => {
  for (const widget of document.querySelectorAll('[data-diagram-widget]')) {
    const buttons = [...widget.querySelectorAll('[data-diagram-mode]')];
    const visual = widget.querySelector('[data-diagram-panel="visual"]');
    const code = widget.querySelector('[data-diagram-panel="code"]');
    const copy = widget.querySelector('[data-diagram-copy]');
    const status = widget.querySelector('[data-diagram-status]');
    const source = code?.querySelector('code')?.textContent || '';
    if (!visual || !code || !source) continue;

    const setMode = (mode) => {
      const showCode = mode === 'code';
      visual.hidden = showCode;
      code.hidden = !showCode;
      for (const button of buttons) {
        button.setAttribute('aria-pressed', String(button.dataset.diagramMode === mode));
      }
    };
    for (const button of buttons) {
      button.addEventListener('click', () => setMode(button.dataset.diagramMode));
    }
    copy?.addEventListener('click', async () => {
      try {
        if (!navigator.clipboard?.writeText) throw new Error('Clipboard API unavailable');
        await navigator.clipboard.writeText(source.trim());
        if (status) status.textContent = 'Código copiado';
      } catch (error) {
        // A selected text field is a functional fallback on non-secure contexts.
        setMode('code');
        const selection = window.getSelection();
        const range = document.createRange();
        range.selectNodeContents(code.querySelector('code'));
        selection?.removeAllRanges();
        selection?.addRange(range);
        if (status) status.textContent = 'Selecione e copie o código destacado';
      }
    });

    // Default view does not depend on JS: the inline image is visible.
    setMode('visual');
  }
})();
